import { db } from '../db';
import { Money } from './money';
import { withRetry } from './retry';

const RETRYABLE = new Set(['gateway_timeout', 'rate_limited', 'temporary_decline']);

export class ChargeService {
  async charge(customerId: string, amount: Money, idempotencyKey?: string): Promise<string> {
    const customer = await db.customers.findById(customerId);
    if (!customer) throw new Error('no such customer');

    if (idempotencyKey) {
      const prior = await db.charges.findByIdempotencyKey(idempotencyKey);
      if (prior) return prior.id;
    }

    const charge = await db.charges.insert({
      customerId,
      amountCents: amount.cents,
      currency: amount.currency,
      idempotencyKey: idempotencyKey ?? null,
      status: 'pending',
      attempts: 0,
    });

    const result = await withRetry(
      () => this.gateway.submit(charge.id, amount),
      { attempts: 4, backoffMs: 250, retryOn: (e) => RETRYABLE.has(e.code) },
    );

    await db.charges.update(charge.id, {
      status: result.ok ? 'settled' : 'failed',
      attempts: result.attempts,
      lastError: result.ok ? null : result.error.code,
    });

    if (result.ok) {
      await this.ledger.record({
        chargeId: charge.id,
        debit: { account: `customer:${customerId}`, amountCents: amount.cents },
        credit: { account: 'revenue:charges', amountCents: amount.cents },
      });
    }
    return charge.id;
  }

  async void(chargeId: string): Promise<void> {
    const charge = await db.charges.findById(chargeId);
    if (!charge) throw new Error('no such charge');
    if (charge.status === 'settled') throw new Error('settled charges must be refunded, not voided');
    await db.charges.update(chargeId, { status: 'voided' });
  }
}

