import { db } from '../db';

export class RefundService {
  async refund(chargeId: string, amountCents: number, reason: string) {
    const charge = await db.charges.findById(chargeId);
    if (!charge) throw new Error('no such charge');
    if (charge.status !== 'settled') throw new Error('only settled charges can be refunded');

    const already = await db.refunds.sumByCharge(chargeId);
    if (already + amountCents > charge.amountCents) {
      throw new Error('refund would exceed the original charge');
    }

    const refund = await db.refunds.insert({
      chargeId,
      amountCents,
      reason,
      status: 'pending',
    });

    const res = await this.gateway.refund(charge.gatewayRef, amountCents);
    await db.refunds.update(refund.id, {
      status: res.ok ? 'settled' : 'failed',
      gatewayRef: res.ref ?? null,
    });

    if (res.ok) {
      await this.ledger.record({
        refundId: refund.id,
        debit: { account: 'revenue:charges', amountCents },
        credit: { account: `customer:${charge.customerId}`, amountCents },
      });
    }
    return res.ok;
  }
}

