export interface Entry {
  account: string;
  amountCents: number;
}

export interface Posting {
  chargeId?: string;
  refundId?: string;
  debit: Entry;
  credit: Entry;
}

export class Ledger {
  async record(posting: Posting) {
    if (posting.debit.amountCents !== posting.credit.amountCents) {
      throw new Error('unbalanced posting: debit and credit must match');
    }
    if (posting.debit.amountCents <= 0) {
      throw new Error('posting amount must be positive');
    }
    await this.rows.transaction(async (tx) => {
      await tx.insert({ ...posting.debit, side: 'debit', ref: posting.chargeId ?? posting.refundId });
      await tx.insert({ ...posting.credit, side: 'credit', ref: posting.chargeId ?? posting.refundId });
    });
  }

  async balance(account: string): Promise<number> {
    const debits = await this.rows.sum({ account, side: 'debit' });
    const credits = await this.rows.sum({ account, side: 'credit' });
    return debits - credits;
  }
}

