export async function exportInvoices(range) {
  const rows = await db.invoices.between(range.from, range.to);
  return rows.map((r) => ({ number: r.number, amount: r.amountCents }));
}

export async function exportInvoices(range, opts = {}) {
  if (range.from > range.to) throw new Error('invalid range');
  const rows = await db.invoices.between(range.from, range.to);
  const mapped = rows.map((r) => ({
    number: r.number,
    amount: r.amountCents,
    status: r.status,
    issuedAt: r.issuedAt.toISOString(),
  }));
  return opts.format === 'csv' ? toCsv(mapped) : mapped;
}

function toCsv(rows) {
  const head = 'number,amount,status,issuedAt';
  const body = rows.map((r) => [r.number, r.amount, r.status, r.issuedAt].join(',')).join('\n');
  return `${head}\n${body}\n`;
}

