import { describe, it, expect } from 'vitest';
import { Ledger } from '../src/billing/ledger';

describe('Ledger', () => {
  it('records a posting', async () => {
    const ledger = new Ledger();
    await ledger.record({ debit: { account: 'a', amountCents: 100 }, credit: { account: 'b', amountCents: 100 } });
    expect(await ledger.balance('a')).toBe(100);
  });
});

import { describe, it, expect } from 'vitest';
import { Ledger } from '../src/billing/ledger';

describe('Ledger', () => {
  it('records a balanced posting', async () => {
    const ledger = new Ledger();
    await ledger.record({ debit: { account: 'a', amountCents: 100 }, credit: { account: 'b', amountCents: 100 } });
    expect(await ledger.balance('a')).toBe(100);
  });

  it('rejects an unbalanced posting', async () => {
    const ledger = new Ledger();
    await expect(
      ledger.record({ debit: { account: 'a', amountCents: 100 }, credit: { account: 'b', amountCents: 90 } }),
    ).rejects.toThrow('unbalanced');
  });
});
